from decimal import Decimal, DecimalException, localcontext

def generate():
    return []

def check(reply, clue):
    actual = reply.split()
    expected = str(clue).split()
    if len(actual) != 1 or len(expected) != 1:
        return False
    try:
        with localcontext() as context:
            context.prec = 60
            value, reference = Decimal(actual[0]), Decimal(expected[0])
            if not value.is_finite() or not reference.is_finite():
                return False
            tolerance = max(Decimal("1e-9"), Decimal("1e-9") * abs(reference))
            return abs(value - reference) <= tolerance
    except (DecimalException, ValueError, TypeError):
        return False
